// The studio HUD and notifications. Every title and action bar message goes through this module.
// - HUD: what it shows rides in the title text behind an invisible prefix; RP/ui/hud_screen.json (generated by
//   tools/gen_hud.py) draws it as the MINE-OS board at the top left. The profile (name, rank, level, XP) rides in the
//   subtitle of the same title and gets its own panel at the top right. There are no plain titles any more.
// - Notifications: the action bar, drawn as a MINE-OS card (glass, cyan rim, flicker-in, light sweep, timer line).
//   Every message makes a new card (and replays its entrance), so they take turns: a toast stays up long enough to
//   read before the next card replaces it, small messages in quick succession are bundled (only the latest shows, a
//   moment later) and pickups count up ("+4 Coal"). At most two toasts wait, so nothing shows long after the fact.
import { system } from '@minecraft/server';

/** Invisible prefixes (formatting codes) - must match tools/gen_hud.py. */
export const HUD_CODES = { home: '§h§u§1', run: '§h§u§2', profile: '§p§f§1', doors: '§d§o§r' };
const SEGMENTS = '123456789a';
/** Light bar level 0..10 inside a run HUD text: one mark per lit segment (the HUD tests each mark on its own). */
export const levelMark = (n) => [...SEGMENTS.slice(0, Math.max(0, Math.min(10, n)))].map((c) => `§q§q§${c}`).join('');

const cards = new Map(); // playerId -> { priority, sent, hold } of the card on screen (hold: ticks it stays at least)
const queues = new Map(); // playerId -> { toasts: [], small, timer } of the cards still to show
const combos = new Map(); // playerId -> { name, count, tick } of the last pickup
const GAP = 14; // ticks a small card stays before the next one
const READ = 40; // ticks a toast stays before the next toast (30 before a small message); the card shows ~3.7 s
const WAITING = 2; // toasts that may wait; a newer one pushes out the oldest
const shown = new Map(); // playerId -> the HUD title last sent
const profiles = new Map(); // playerId -> the profile (subtitle) last sent
const doorsUntil = new Map(); // playerId -> tick until which the title carries the door code (arrival)
const sentAt = new Map(); // playerId -> tick it was sent (re-sent every few seconds so it never runs out)

function send(player, title) {
  const now = system.currentTick;
  sentAt.set(player.id, now);
  const until = doorsUntil.get(player.id);
  if (until !== undefined && now >= until) doorsUntil.delete(player.id);
  try {
    player.onScreenDisplay.setTitle((doorsUntil.has(player.id) ? HUD_CODES.doors : '') + title, { fadeInDuration: 0, stayDuration: 400, fadeOutDuration: 0, subtitle: profiles.get(player.id) ?? ' ' });
  } catch {
    // the player is leaving or not loaded yet
  }
}

/** Show the HUD: mode 'home' or 'run', text with \n between lines; level (0..10) fills the light bar of a run. */
export function showHud(player, mode, text, level) {
  const title = HUD_CODES[mode] + (level === undefined ? '' : levelMark(level)) + text;
  if (shown.get(player.id) === title && system.currentTick - (sentAt.get(player.id) ?? -999) < 100) return;
  shown.set(player.id, title);
  send(player, title);
}

/** A notification card. priority: 1 small (pickups, refusals) or 2 important (toasts; seconds: least time on screen). */
export function notify(player, text, priority = 1, seconds = 2.5) {
  let q = queues.get(player.id);
  if (!q) queues.set(player.id, (q = { toasts: [], small: undefined, timer: undefined }));
  const card = { text, priority, seconds };
  if (priority < 2) q.small = card;
  else if (q.toasts.push(card) > WAITING) q.toasts.shift();
  if (priority >= 2 && q.timer !== undefined && cards.get(player.id)?.priority < 2) {
    system.clearRun(q.timer); // only a small card is up: the toast need not wait for it
    q.timer = undefined;
  }
  pump(player, q);
  return true;
}

function pump(player, q) {
  if (q.timer !== undefined || (!q.toasts.length && !q.small)) return;
  const now = system.currentTick;
  const live = cards.get(player.id);
  const toastNext = q.toasts.length > 0;
  let wait = 0;
  if (live?.priority < 2) wait = toastNext ? 0 : live.sent + GAP - now; // a toast cuts a small card short
  else if (live) wait = live.sent + Math.min(live.hold, toastNext ? READ : READ - 10) - now;
  if (wait > 0) {
    q.timer = system.runTimeout(() => {
      q.timer = undefined;
      if (player.isValid && queues.get(player.id) === q) pump(player, q);
    }, wait);
    return;
  }
  const card = q.toasts.shift() ?? q.small;
  if (card === q.small) q.small = undefined;
  cards.set(player.id, { priority: card.priority, sent: now, hold: Math.round(card.seconds * 20) });
  try {
    player.onScreenDisplay.setActionBar(card.text);
  } catch {
    return; // the player is leaving
  }
  pump(player, q);
}

/** A pickup ("+1 Coal"); picking the same thing again within 2.5 s counts up ("+4 Coal"). tail: more on the line. */
export function pickup(player, name, tail = '') {
  const now = system.currentTick;
  const last = combos.get(player.id);
  const count = last?.name === name && now - last.tick < 50 ? last.count + 1 : 1;
  combos.set(player.id, { name, count, tick: now });
  notify(player, `§e+${count} ${name}${tail}`, 1, 1.2);
}

/** An important notification: a gold first line and an optional white second line. */
export function toast(player, title, line = '', seconds = 3) {
  notify(player, `§6${title}${line ? `\n§f${line}` : ''}`, 2, seconds);
}

/**
 * The profile panel: text with \n between lines, level (0..10) fills its XP bar, rank (1..7) picks the badge. Shown
 * with the HUD only (sent with the next HUD title, or now when a HUD is up).
 */
export function showProfile(player, text, level, rank) {
  const subtitle = `${HUD_CODES.profile}§z§z§${rank}${levelMark(level)}${text}`;
  if (profiles.get(player.id) === subtitle) return;
  profiles.set(player.id, subtitle);
  if (shown.has(player.id)) send(player, shown.get(player.id));
}

/**
 * Arrival: the MINE-OS blast doors the loading screen closed stand shut over the world and slide apart. The door code
 * rides in the title for under a second (the doors take 0.65 s), then the title is sent again without it.
 */
export function openDoors(player) {
  const until = system.currentTick + 16;
  doorsUntil.set(player.id, until);
  send(player, shown.get(player.id) ?? ' ');
  system.runTimeout(() => {
    if (player.isValid && doorsUntil.get(player.id) === until) send(player, shown.get(player.id) ?? ' ');
  }, 17);
}

/** No HUD (not playing a session). */
export function clearHud(player) {
  shown.delete(player.id);
  profiles.delete(player.id);
  send(player, ' ');
}

export function forgetHud(playerId) {
  cards.delete(playerId);
  queues.delete(playerId);
  combos.delete(playerId);
  shown.delete(playerId);
  profiles.delete(playerId);
  doorsUntil.delete(playerId);
  sentAt.delete(playerId);
}
